def page(items: list, number: int, size: int) -> list:
    start = (number - 1) * size
    return items[start:start + size]

import pytest

from catalog.pager import page


@pytest.mark.parametrize(
    ("number", "size", "expected"),
    [
        (1, 2, [0, 1]),
        (2, 2, [2, 3]),
        (3, 2, [4]),
        (4, 2, []),
        (1, 10, [0, 1, 2, 3, 4]),
    ],
)
def test_page_uses_one_based_numbers(number, size, expected):
    assert page([0, 1, 2, 3, 4], number, size) == expected


def test_page_of_empty_items():
    assert page([], 1, 2) == []
